<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pembayaran</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body><header class="navbar"><div class="container-xl"><a class="navbar-brand" href="{{ route('dashboard') }}">Cake Store Management</a></div></header><main class="page-wrapper"><div class="container-xl py-4"><h2>Pembayaran</h2><x-flash /><div class="card"><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Nota</th><th>Pelanggan</th><th>Total</th><th>Terbayar</th><th>Sisa</th><th>Status</th><th></th></tr></thead><tbody>@forelse($orders as $order)@php($remaining = (float) $order->total - (float) ($order->payments_sum_amount ?? 0))<tr><td>{{ $order->document_number }}</td><td>{{ $order->customer?->name ?: 'POS anonim' }}</td><td>Rp {{ number_format($order->total, 2, ',', '.') }}</td><td>Rp {{ number_format($order->payments_sum_amount ?? 0, 2, ',', '.') }}</td><td>Rp {{ number_format($remaining, 2, ',', '.') }}</td><td>{{ strtoupper(str_replace('_', ' ', $order->payment_status ?? 'unpaid')) }}</td><td>@if($remaining > 0)<a class="btn btn-primary btn-sm" href="{{ route('payments.create', $order) }}">Catat pembayaran</a>@else<span class="badge bg-success-lt">Lunas</span>@endif</td></tr>@empty<tr><td colspan="6" class="text-center text-secondary">Belum ada order.</td></tr>@endforelse</tbody></table></div></div><div class="card-footer"><h3 class="mb-3">Riwayat pembayaran</h3>@foreach($orders as $order)@foreach($order->payments as $payment)<div class="d-flex justify-content-between align-items-center border-bottom py-2"><span>{{ $order->document_number }}: Rp {{ number_format($payment->amount, 2, ',', '.') }} ({{ strtoupper($payment->method) }})</span>@if($payment->reversal_of_id === null)<form method="POST" action="{{ route('payments.reverse', $payment) }}" data-reason-form>@csrf<input name="reason" type="hidden" value="Koreksi pembayaran"><button class="btn btn-outline-danger btn-sm" data-confirm="Batalkan pembayaran ini?" type="submit">Batalkan</button></form>@endif</div>@endforeach @endforeach</div></div></div></main></body></html>
